<?php
namespace Tests\Feature;
use App\Livewire\Investor\Support\{Index,Show};use App\Models\{InvestmentAccount,Investor,SupportMessage,SupportTicket,User};use App\Services\SupportTicketService;use Illuminate\Foundation\Testing\RefreshDatabase;use Livewire\Livewire;use Tests\TestCase;
class InvestorSupportUiTest extends TestCase{use RefreshDatabase;public function test_index_create_view_reply_closed_and_internal_security():void{[$investor,$user]=$this->context();$admin=User::factory()->create(['role'=>'admin','is_active'=>true]);$this->actingAs($user)->get('/support')->assertOk()->assertSee('Ваши вопросы и обращения');Livewire::actingAs($user)->test(Index::class)->set('category','accruals')->set('subject','Вопрос')->set('message','Текст')->set('priority','high')->call('create')->assertHasNoErrors();$ticket=SupportTicket::sole();app(SupportTicketService::class)->addInternalNote($ticket,$admin,'Скрытая заметка');Livewire::actingAs($user)->test(Show::class,['supportTicket'=>$ticket])->assertSee('Текст')->assertDontSee('Скрытая заметка')->set('message','Ответ')->call('reply')->assertHasNoErrors();app(SupportTicketService::class)->changeStatus($ticket,$admin,'closed');Livewire::actingAs($user)->test(Show::class,['supportTicket'=>$ticket->fresh()])->assertSee('Обращение закрыто.');}
public function test_ownership_and_validation():void{[$one,$user]=$this->context();[$two,$other]=$this->context();$ticket=app(SupportTicketService::class)->create($two,$other,'general','Чужое','Текст');$this->actingAs($user)->get('/support/'.$ticket->id)->assertNotFound();Livewire::actingAs($user)->test(Index::class)->set('category','bad')->set('subject','')->set('message','')->set('priority','urgent')->call('create')->assertHasErrors(['category','subject','message','priority']);}
private function context():array{$u=User::factory()->create(['role'=>'investor','is_active'=>true]);$i=Investor::create(['user_id'=>$u->id,'code'=>'UI-'.User::count(),'status'=>'active']);InvestmentAccount::create(['investor_id'=>$i->id,'currency'=>'USDT','status'=>'active']);return[$i,$u];}}
